PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE clients (id TEXT PRIMARY KEY, green_invoice_id TEXT UNIQUE, name TEXT NOT NULL, tax_id TEXT, email TEXT, phone TEXT, status TEXT DEFAULT 'active', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, tenant_id TEXT REFERENCES tenants(id));
CREATE TABLE generic_documents (id TEXT PRIMARY KEY, collection TEXT NOT NULL, data JSON NOT NULL, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, client_id TEXT, status TEXT DEFAULT 'active', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, tenant_id TEXT REFERENCES tenants(id), FOREIGN KEY(client_id) REFERENCES clients(id));
CREATE TABLE tasks (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, status TEXT DEFAULT 'todo', project_id TEXT, assignee TEXT, due_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, tenant_id TEXT REFERENCES tenants(id), FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE suppliers (id TEXT PRIMARY KEY, name TEXT NOT NULL, contact_info TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE domains (id TEXT PRIMARY KEY, domain_name TEXT NOT NULL UNIQUE, registrar TEXT, expiry_date DATE, is_active INTEGER DEFAULT 1, status TEXT DEFAULT 'ok', updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE system_logs (id INTEGER PRIMARY KEY, msg TEXT);
CREATE TABLE tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
